"use strict";function addDuplicateField(n){var r,i;n.preventDefault();var f=n.target.getAttribute("data-container"),t=document.getElementById(f),u=t.firstElementChild;u&&(r=u.cloneNode(!0),t.appendChild(r),i=document.createElement("button"),i.textContent="Remove",i.classList.add("govuk-button","govuk-button--secondary"),i.addEventListener("click",function(){t.removeChild(r);t.removeChild(i);t.children.length===1&&t.removeChild(t.querySelector(".remove-button"))}),t.appendChild(i))}var addButtons=document.querySelectorAll(".add-another-answer");addButtons.forEach(function(n){n.addEventListener("click",addDuplicateField)});document.getElementById("save-and-return").addEventListener("click",function(){document.getElementById("show-next-question").value="false";document.querySelector("form").submit()});